def main():
    n, k = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(n)]
    M = 998244353
    def mm(X, Y): return [[sum(X[i][t] * Y[t][j] for t in range(n)) % M for j in range(n)] for i in range(n)]
    R_ = [[int(i == j) for j in range(n)] for i in range(n)]
    while k:
        if k & 1: R_ = mm(R_, A)
        A = mm(A, A); k >>= 1
    print(sum(R_[i][i] for i in range(n)) % M)
